<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import FieldError from '../../../components/FieldError.vue';
import StatusNotice from '../../../components/StatusNotice.vue';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface ReturnItem { id: string; order_item_id: string; product_variant_id: string | null; product_name: string; variant_name: string | null; sku: string; ordered_quantity: number; fulfilled_quantity: number; returnable_quantity: number; requested_quantity: number; received_quantity: number; accepted_quantity: number; restocked_quantity: number; reason: string | null; condition: string | null; disposition: string | null; inspection_notes: string | null; inspected_at: string | null }
interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string | null }
interface ReturnRecord { id: string; short_id: string; status: string; reason: string | null; notes: string | null; rejection_reason: string | null; cancellation_reason: string | null; requested_at: string | null; approved_at: string | null; rejected_at: string | null; received_at: string | null; inspection_started_at: string | null; completed_at: string | null; cancelled_at: string | null; order: { id: string; order_number: string; customer_id: string | null; customer_name: string; email: string | null; phone: string | null }; items: ReturnItem[]; history: History[] }
interface Refund { id: string; status: string; amount: string; currency: string; reason: string; completed_at: string | null; created_at: string | null }
interface Exchange { id: string; short_id: string; status: string; item_count: number; approved_at: string | null; completed_at: string | null; cancelled_at: string | null; created_at: string | null }
interface Location { id: string; name: string; code: string }
interface ReplacementVariant { id: string; product_name: string; name: string | null; sku: string }
interface Capabilities { manage: boolean; inspect: boolean; restock: boolean; view_refunds: boolean; manage_exchanges: boolean; approve: boolean; reject: boolean; receive: boolean; complete: boolean; cancel: boolean; create_exchange: boolean }
interface ExchangeLine { return_item_id: string; replacement_product_variant_id: string; quantity: number }

const props = defineProps<{ return: ReturnRecord; refunds: Refund[] | null; exchanges: Exchange[]; locations: Location[]; replacementVariants: ReplacementVariant[]; conditions: string[]; dispositions: string[]; capabilities: Capabilities }>();
const { t, locale } = useI18n();
const returnRequest = computed(() => props.return);
const page = usePage<PageProps>();
const noticeKeys: Record<string, string> = { 'Return approved.': 'approved', 'Return rejected.': 'rejected', 'Return received.': 'received', 'Return completed.': 'completed', 'Return cancelled.': 'cancelled', 'Return item inspected.': 'inspected', 'Return item restocked.': 'restocked', 'Exchange created.': 'exchangeCreated' };
const errorKeys: Record<string, string> = {
    'A rejection reason is required.': 'rejectionReason', 'A cancellation reason is required.': 'cancellationReason', 'Only an approved return can be received.': 'receiveState', 'At least one received item is required.': 'receiveItems', 'Each return item may appear only once.': 'uniqueItems', 'A received item is outside this return, store, or tenant.': 'foreignReceivedItem', 'Every return item must be included when receiving the return.': 'allItemsRequired', 'Received quantity must be within the requested quantity.': 'receivedQuantity', 'Only a received return can be inspected.': 'inspectState', 'Inspection cannot change after restock or exchange allocation.': 'inspectionLocked', 'Accepted quantity exceeds the received or returnable quantity.': 'acceptedQuantity', 'Only an inspecting return can be restocked.': 'restockState', 'Only the accepted unrestocked balance of a RESTOCK item can be restocked.': 'restockQuantity', 'Returns can only be restocked into an active tenant location.': 'activeLocation', 'Only an inspecting return can be completed.': 'completeState', 'Every return item must be inspected before completion.': 'inspectAll', 'Every accepted RESTOCK quantity must be restocked before completion.': 'restockAll', 'An exchange requires at least one item.': 'exchangeItems', 'Exchanges require inspected accepted return items.': 'exchangeState', 'An exchange item is outside this return, store, or tenant.': 'foreignExchangeItem', 'A replacement variant is outside this tenant.': 'foreignVariant', 'Exchange quantity exceeds the unallocated accepted quantity.': 'exchangeQuantity',
};
const statusNotice = computed(() => { const value = page.props.status; return value && noticeKeys[value] ? t(`returns.notices.${noticeKeys[value]}`) : value; });
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const approveForm = useForm({});
const completeForm = useForm({});
const rejectForm = useForm({ reason: '' });
const cancelForm = useForm({ reason: '' });
const receiveForm = useForm<{ items: { return_item_id: string; quantity: number }[] }>({ items: props.return.items.map((item) => ({ return_item_id: item.id, quantity: item.requested_quantity })) });
const inspectForms = Object.fromEntries(props.return.items.map((item) => [item.id, useForm({ condition: item.condition ?? props.conditions[0] ?? '', disposition: item.disposition ?? props.dispositions[0] ?? '', accepted_quantity: item.inspected_at ? item.accepted_quantity : item.received_quantity, notes: item.inspection_notes ?? '' })]));
const restockForms = Object.fromEntries(props.return.items.map((item) => [item.id, useForm({ inventory_location_id: props.locations[0]?.id ?? '', quantity: Math.max(item.accepted_quantity - item.restocked_quantity, 0) })]));
const initialExchangeLines = (): ExchangeLine[] => props.return.items.filter((item) => item.accepted_quantity > 0).map((item) => ({ return_item_id: item.id, replacement_product_variant_id: props.replacementVariants[0]?.id ?? '', quantity: item.accepted_quantity }));
const exchangeForm = useForm<{ items: ExchangeLine[] }>({ items: initialExchangeLines() });
const totalRequested = computed(() => props.return.items.reduce((total, item) => total + item.requested_quantity, 0));
const totalReceived = computed(() => props.return.items.reduce((total, item) => total + item.received_quantity, 0));
const totalAccepted = computed(() => props.return.items.reduce((total, item) => total + item.accepted_quantity, 0));
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : t('common.notAvailable');
const errorFor = (errors: Record<string, string | undefined>, ...keys: string[]) => keys.map((key) => errors[key]).find(Boolean);
const localizedError = (message?: string) => message && errorKeys[message] ? t(`returns.errors.${errorKeys[message]}`) : message;
const itemFor = (id: string) => props.return.items.find((item) => item.id === id);
const approve = () => { if (window.confirm(t('returns.approveConfirm'))) approveForm.post(`/admin/returns/${props.return.id}/approve`, { preserveScroll: true }); };
const complete = () => { if (window.confirm(t('returns.completeConfirm'))) completeForm.post(`/admin/returns/${props.return.id}/complete`, { preserveScroll: true }); };
const reject = () => { if (window.confirm(t('returns.rejectConfirm'))) rejectForm.post(`/admin/returns/${props.return.id}/reject`, { preserveScroll: true }); };
const cancel = () => { if (window.confirm(t('returns.cancelConfirm'))) cancelForm.post(`/admin/returns/${props.return.id}/cancel`, { preserveScroll: true }); };
const receive = () => receiveForm.post(`/admin/returns/${props.return.id}/receive`, { preserveScroll: true });
const inspect = (item: ReturnItem) => inspectForms[item.id].post(`/admin/return-items/${item.id}/inspect`, { preserveScroll: true });
const restock = (item: ReturnItem) => restockForms[item.id].post(`/admin/return-items/${item.id}/restock`, { preserveScroll: true });
const createExchange = () => exchangeForm.post(`/admin/returns/${props.return.id}/exchanges`, { preserveScroll: true });
const resetExchangeLines = () => { exchangeForm.items = initialExchangeLines(); exchangeForm.clearErrors(); };
</script>

<template>
    <Head :title="t('returns.detailTitle', { id: returnRequest.short_id })" />
    <AdminLayout><div class="space-y-6">
        <Breadcrumbs :items="[{ label: t('nav.operations') }, { label: t('returns.title'), href: '/admin/returns' }, { label: returnRequest.short_id }]" />
        <PageHeader :title="t('returns.detailTitle', { id: returnRequest.short_id })" :eyebrow="t('returns.operationalRecord')" :description="t('returns.detailDescription', { order: returnRequest.order.order_number, date: formatDate(returnRequest.requested_at) })"><template #actions><Link :href="`/admin/orders/${returnRequest.order.id}`" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold hover:bg-slate-50">{{ t('returns.openOrder') }}</Link></template></PageHeader>
        <StatusNotice :message="statusNotice" />

        <section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" :aria-label="t('returns.summary')"><article class="admin-card p-3"><p class="admin-label">{{ t('common.status') }}</p><div class="mt-2"><StatusBadge :status="returnRequest.status" /></div></article><article class="admin-card p-3"><p class="admin-label">{{ t('returns.requestedUnits') }}</p><p class="mt-1 font-mono text-lg font-semibold">{{ totalRequested }}</p><p class="text-xs text-admin-neutral">{{ t('returns.lineCount', { count: returnRequest.items.length }) }}</p></article><article class="admin-card p-3"><p class="admin-label">{{ t('returns.receivedUnits') }}</p><p class="mt-1 font-mono text-lg font-semibold">{{ totalReceived }}</p></article><article class="admin-card p-3"><p class="admin-label">{{ t('returns.acceptedUnits') }}</p><p class="mt-1 font-mono text-lg font-semibold">{{ totalAccepted }}</p></article></section>

        <section v-if="capabilities.approve || capabilities.complete" class="admin-card flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="admin-label text-admin-secondary">{{ t('returns.nextOperation') }}</p><p class="mt-1 text-sm text-admin-neutral">{{ t('returns.operationHelp') }}</p></div><div class="grid gap-2 sm:flex"><button v-if="capabilities.approve" :disabled="approveForm.processing" class="rounded-md bg-admin-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50" @click="approve">{{ approveForm.processing ? t('returns.processing') : t('returns.approve') }}</button><button v-if="capabilities.complete" :disabled="completeForm.processing" class="rounded-md border border-admin-success-border bg-admin-success-bg px-4 py-2.5 text-sm font-semibold text-admin-success disabled:opacity-50" @click="complete">{{ completeForm.processing ? t('returns.processing') : t('returns.complete') }}</button></div></section>
        <FieldError :message="localizedError(serverErrors.return ?? serverErrors.items)" />

        <section class="grid gap-5 lg:grid-cols-[minmax(0,3fr)_minmax(18rem,2fr)]"><div><p class="admin-label text-admin-secondary">{{ t('returns.contextSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('returns.returnContext') }}</h2><div class="admin-card mt-4 divide-y divide-admin-border px-4"><div class="grid gap-3 py-3 sm:grid-cols-2"><div><p class="admin-label">{{ t('returns.customer') }}</p><p class="mt-1 text-sm font-semibold">{{ returnRequest.order.customer_name }}</p><p class="mt-1 break-all text-xs text-admin-neutral">{{ returnRequest.order.email ?? t('returns.noEmail') }} · {{ returnRequest.order.phone ?? t('returns.noPhone') }}</p></div><div><p class="admin-label">{{ t('returns.order') }}</p><Link :href="`/admin/orders/${returnRequest.order.id}`" class="admin-link mt-1 inline-flex font-mono text-sm font-semibold">{{ returnRequest.order.order_number }}</Link></div></div><div class="grid gap-3 py-3 sm:grid-cols-2"><div><p class="admin-label">{{ t('returns.overallReason') }}</p><p class="mt-1 text-sm">{{ returnRequest.reason ?? t('returns.notProvided') }}</p></div><div><p class="admin-label">{{ t('returns.internalNotes') }}</p><p class="mt-1 whitespace-pre-wrap text-sm">{{ returnRequest.notes ?? t('returns.notProvided') }}</p></div></div><div v-if="returnRequest.rejection_reason || returnRequest.cancellation_reason" class="py-3 text-xs"><p v-if="returnRequest.rejection_reason"><strong>{{ t('returns.rejectionReason') }}:</strong> {{ returnRequest.rejection_reason }}</p><p v-if="returnRequest.cancellation_reason"><strong>{{ t('returns.cancellationReason') }}:</strong> {{ returnRequest.cancellation_reason }}</p></div></div></div>
            <aside><p class="admin-label text-admin-secondary">{{ t('returns.historySection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('returns.history') }}</h2><ol class="admin-card mt-4 divide-y divide-admin-border px-4"><li v-for="entry in returnRequest.history" :key="entry.id" class="py-3"><div class="flex flex-wrap items-center gap-2"><StatusBadge v-if="entry.from_status" :status="entry.from_status" /><span v-else class="font-mono text-[10px] text-admin-neutral">{{ t('returns.createdState') }}</span><span aria-hidden="true">→</span><StatusBadge :status="entry.to_status" /></div><p class="mt-2 text-xs text-admin-neutral">{{ formatDate(entry.created_at) }} · {{ entry.actor ?? t('returns.systemActor') }}</p><p v-if="entry.reason" class="mt-1 text-xs">{{ entry.reason }}</p></li></ol></aside></section>

        <form v-if="capabilities.receive" class="rounded-lg border border-admin-info-border bg-admin-info-bg p-4" @submit.prevent="receive"><p class="admin-label text-admin-secondary">{{ t('returns.receivingSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('returns.receive') }}</h2><p class="mt-1 text-xs text-admin-text-secondary">{{ t('returns.receiveHelp') }}</p><div class="mt-4 grid gap-2"><label v-for="(item, index) in returnRequest.items" :key="item.id" class="grid items-center gap-2 rounded-md border border-admin-info-border bg-white p-3 sm:grid-cols-[minmax(0,1fr)_7rem]"><span class="min-w-0"><strong class="block truncate text-sm">{{ item.product_name }}</strong><span class="font-mono text-xs text-admin-neutral">{{ item.sku }} · {{ t('returns.requestedCount', { count: item.requested_quantity }) }}</span></span><span><span class="sr-only">{{ t('returns.receivedQuantityFor', { product: item.product_name }) }}</span><input v-model.number="receiveForm.items[index].quantity" required type="number" min="1" :max="item.requested_quantity" class="admin-control w-full px-3 font-mono text-sm" /></span></label></div><FieldError :message="localizedError(errorFor(receiveForm.errors as Record<string, string | undefined>, 'items', 'items.0.quantity', 'items.0.return_item_id') ?? serverErrors.quantity ?? serverErrors.return)" /><button :disabled="receiveForm.processing" class="mt-3 w-full rounded-md bg-admin-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50 sm:w-auto">{{ receiveForm.processing ? t('returns.processing') : t('returns.confirmReceipt') }}</button></form>

        <section><p class="admin-label text-admin-secondary">{{ t('returns.itemsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('returns.returnItems') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('returns.itemsHelp') }}</p><div class="mt-4 grid gap-4"><article v-for="item in returnRequest.items" :key="item.id" class="admin-card min-w-0 p-4"><div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div class="min-w-0"><h3 class="truncate text-sm font-semibold" :title="item.product_name">{{ item.product_name }}</h3><p class="mt-0.5 text-xs text-admin-neutral">{{ item.variant_name ?? t('returns.defaultVariant') }}</p><p class="mt-2 break-all font-mono text-xs">{{ item.sku }}</p><p v-if="item.reason" class="mt-2 text-xs">{{ item.reason }}</p></div><dl class="grid grid-cols-3 gap-px overflow-hidden rounded-md bg-admin-border text-center"><div v-for="metric in [{ label: t('returns.requested'), value: item.requested_quantity }, { label: t('returns.received'), value: item.received_quantity }, { label: t('returns.accepted'), value: item.accepted_quantity }]" :key="metric.label" class="min-w-20 bg-admin-canvas p-2"><dt class="admin-label">{{ metric.label }}</dt><dd class="mt-1 font-mono text-base font-semibold">{{ metric.value }}</dd></div></dl></div>
                <dl class="mt-4 grid gap-2 border-t border-admin-border pt-3 text-xs sm:grid-cols-4"><div><dt class="admin-label">{{ t('returns.ordered') }}</dt><dd class="mt-1 font-mono">{{ item.ordered_quantity }}</dd></div><div><dt class="admin-label">{{ t('returns.fulfilled') }}</dt><dd class="mt-1 font-mono">{{ item.fulfilled_quantity }}</dd></div><div><dt class="admin-label">{{ t('returns.returnableBalance') }}</dt><dd class="mt-1 font-mono">{{ item.returnable_quantity }}</dd></div><div><dt class="admin-label">{{ t('returns.restocked') }}</dt><dd class="mt-1 font-mono">{{ item.restocked_quantity }} / {{ item.accepted_quantity }}</dd></div></dl>
                <div v-if="item.inspected_at" class="mt-4 grid gap-3 rounded-md border border-admin-border bg-admin-canvas p-3 text-xs sm:grid-cols-3"><div><span class="admin-label">{{ t('returns.condition') }}</span><p class="mt-1 font-semibold">{{ item.condition ? t(`returns.conditions.${item.condition}`) : t('common.notAvailable') }}</p></div><div><span class="admin-label">{{ t('returns.disposition') }}</span><p class="mt-1 font-semibold">{{ item.disposition ? t(`returns.dispositions.${item.disposition}`) : t('common.notAvailable') }}</p></div><div><span class="admin-label">{{ t('returns.inspectionNotes') }}</span><p class="mt-1 whitespace-pre-wrap">{{ item.inspection_notes ?? t('common.none') }}</p></div></div>
                <form v-if="capabilities.inspect && ['RECEIVED', 'INSPECTING'].includes(returnRequest.status)" class="mt-4 grid gap-3 rounded-md border border-admin-border bg-admin-canvas p-3 sm:grid-cols-3" @submit.prevent="inspect(item)"><label class="grid gap-1.5 text-xs font-medium">{{ t('returns.condition') }}<select v-model="inspectForms[item.id].condition" required class="admin-control px-3 text-sm"><option v-for="condition in conditions" :key="condition" :value="condition">{{ t(`returns.conditions.${condition}`) }}</option></select></label><label class="grid gap-1.5 text-xs font-medium">{{ t('returns.disposition') }}<select v-model="inspectForms[item.id].disposition" required class="admin-control px-3 text-sm"><option v-for="disposition in dispositions" :key="disposition" :value="disposition">{{ t(`returns.dispositions.${disposition}`) }}</option></select></label><label class="grid gap-1.5 text-xs font-medium">{{ t('returns.acceptedQuantity') }}<input v-model.number="inspectForms[item.id].accepted_quantity" required type="number" min="0" :max="item.received_quantity" class="admin-control px-3 font-mono text-sm" /></label><label class="grid gap-1.5 text-xs font-medium sm:col-span-3">{{ t('returns.inspectionNotes') }}<textarea v-model="inspectForms[item.id].notes" maxlength="5000" class="admin-control min-h-20 p-3 text-sm" /></label><div class="sm:col-span-3"><FieldError :message="localizedError(errorFor(inspectForms[item.id].errors as Record<string, string | undefined>, 'condition', 'disposition', 'accepted_quantity', 'notes', 'item', 'return') ?? serverErrors.item)" /><button :disabled="inspectForms[item.id].processing" class="mt-2 w-full rounded-md bg-admin-primary px-4 py-2 text-xs font-semibold text-white disabled:opacity-50 sm:w-auto">{{ inspectForms[item.id].processing ? t('returns.processing') : item.inspected_at ? t('returns.updateInspection') : t('returns.recordInspection') }}</button></div></form>
                <form v-if="capabilities.restock && returnRequest.status === 'INSPECTING' && item.disposition === 'RESTOCK' && item.accepted_quantity > item.restocked_quantity" class="mt-3 grid gap-3 rounded-md border border-admin-success-border bg-admin-success-bg p-3 sm:grid-cols-[minmax(0,1fr)_7rem_auto] sm:items-end" @submit.prevent="restock(item)"><label class="grid gap-1.5 text-xs font-medium">{{ t('returns.activeLocation') }}<select v-model="restockForms[item.id].inventory_location_id" required class="admin-control px-3 text-sm"><option value="" disabled>{{ t('returns.selectLocation') }}</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.code }} · {{ location.name }}</option></select></label><label class="grid gap-1.5 text-xs font-medium">{{ t('returns.quantity') }}<input v-model.number="restockForms[item.id].quantity" required type="number" min="1" :max="item.accepted_quantity - item.restocked_quantity" class="admin-control px-3 font-mono text-sm" /></label><button :disabled="restockForms[item.id].processing || !locations.length" class="rounded-md bg-admin-primary px-4 py-2.5 text-xs font-semibold text-white disabled:opacity-50">{{ restockForms[item.id].processing ? t('returns.processing') : t('returns.restock') }}</button><FieldError class="sm:col-span-3" :message="localizedError(errorFor(restockForms[item.id].errors as Record<string, string | undefined>, 'inventory_location_id', 'quantity', 'location', 'return') ?? serverErrors.quantity ?? serverErrors.location)" /></form>
            </article></div></section>

        <section class="grid gap-5 lg:grid-cols-2"><div><p class="admin-label text-admin-secondary">{{ t('returns.exchangesSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('returns.relatedExchanges') }}</h2><div v-if="exchanges.length" class="mt-4 grid gap-2"><Link v-for="exchange in exchanges" :key="exchange.id" :href="`/admin/exchanges/${exchange.id}`" class="admin-card flex items-center justify-between gap-3 p-3"><div><span class="admin-link font-mono text-xs font-semibold">{{ exchange.short_id }}</span><p class="mt-1 text-[11px] text-admin-neutral">{{ t('returns.exchangeLineCount', { count: exchange.item_count }) }} · {{ formatDate(exchange.created_at) }}</p></div><StatusBadge :status="exchange.status" /></Link></div><EmptyState v-else class="mt-4" :title="t('returns.noExchanges')" :description="t('returns.noExchangesHelp')" />
                <form v-if="capabilities.create_exchange && initialExchangeLines().length && replacementVariants.length" class="admin-card mt-4 p-4" @submit.prevent="createExchange"><div class="flex items-start justify-between gap-3"><div><p class="admin-label text-admin-secondary">{{ t('returns.exchangeCreateSection') }}</p><h3 class="mt-1 text-base font-semibold">{{ t('returns.createExchange') }}</h3><p class="mt-1 text-xs text-admin-neutral">{{ t('returns.createExchangeHelp') }}</p></div><button v-if="exchangeForm.items.length < initialExchangeLines().length" type="button" class="admin-link text-xs" @click="resetExchangeLines">{{ t('returns.resetLines') }}</button></div><div class="mt-3 grid gap-3"><div v-for="(line, index) in exchangeForm.items" :key="line.return_item_id" class="rounded-md border border-admin-border bg-admin-canvas p-3"><div class="flex items-start justify-between gap-2"><p class="truncate text-xs font-semibold">{{ itemFor(line.return_item_id)?.product_name }}</p><button type="button" class="text-xs font-semibold text-admin-danger" :aria-label="t('returns.removeExchangeLine', { product: itemFor(line.return_item_id)?.product_name ?? '' })" @click="exchangeForm.items.splice(index, 1)">{{ t('common.remove') }}</button></div><label class="mt-2 grid gap-1 text-xs">{{ t('returns.replacementVariant') }}<select v-model="line.replacement_product_variant_id" required class="admin-control min-w-0 px-3 text-xs"><option v-for="variant in replacementVariants" :key="variant.id" :value="variant.id">{{ variant.sku }} · {{ variant.product_name }} {{ variant.name ?? '' }}</option></select></label><label class="mt-2 grid gap-1 text-xs">{{ t('returns.quantity') }}<input v-model.number="line.quantity" required type="number" min="1" :max="itemFor(line.return_item_id)?.accepted_quantity" class="admin-control px-3 font-mono text-xs" /></label></div></div><FieldError :message="localizedError(errorFor(exchangeForm.errors as Record<string, string | undefined>, 'items', 'items.0.return_item_id', 'items.0.replacement_product_variant_id', 'items.0.quantity') ?? serverErrors.quantity ?? serverErrors.return)" /><button :disabled="exchangeForm.processing || !exchangeForm.items.length" class="mt-3 w-full rounded-md bg-admin-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{{ exchangeForm.processing ? t('returns.processing') : t('returns.createExchange') }}</button></form>
            </div>
            <div v-if="refunds !== null"><p class="admin-label text-admin-secondary">{{ t('returns.refundsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('returns.relatedRefunds') }}</h2><div v-if="refunds.length" class="mt-4 grid gap-2"><Link v-for="refund in refunds" :key="refund.id" :href="`/admin/refunds/${refund.id}`" class="admin-card flex items-center justify-between gap-3 p-3"><div><p class="font-mono text-sm font-semibold">{{ refund.currency }} {{ refund.amount }}</p><p class="mt-1 text-xs text-admin-neutral">{{ refund.reason }} · {{ formatDate(refund.created_at) }}</p></div><StatusBadge :status="refund.status" /></Link></div><EmptyState v-else class="mt-4" :title="t('returns.noRefunds')" :description="t('returns.noRefundsHelp')" /></div></section>

        <section v-if="capabilities.reject || capabilities.cancel" class="grid gap-4 lg:grid-cols-2"><form v-if="capabilities.reject" class="rounded-lg border border-admin-danger-border bg-admin-danger-bg p-4" @submit.prevent="reject"><p class="admin-label text-admin-danger">{{ t('returns.restrictedSection') }}</p><h2 class="mt-1 text-lg font-semibold text-admin-danger">{{ t('returns.reject') }}</h2><label class="mt-4 grid gap-1.5 text-xs font-medium">{{ t('returns.rejectionReason') }}<textarea v-model="rejectForm.reason" required maxlength="500" class="admin-control min-h-24 p-3" /></label><FieldError :message="localizedError(rejectForm.errors.reason ?? serverErrors.return)" /><button :disabled="rejectForm.processing" class="mt-3 w-full rounded-md border border-admin-danger-border bg-white px-4 py-2.5 text-sm font-semibold text-admin-danger disabled:opacity-50 sm:w-auto">{{ rejectForm.processing ? t('returns.processing') : t('returns.reject') }}</button></form><form v-if="capabilities.cancel" class="rounded-lg border border-admin-warning-border bg-admin-warning-bg p-4" @submit.prevent="cancel"><p class="admin-label">{{ t('returns.restrictedSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('returns.cancelReturn') }}</h2><label class="mt-4 grid gap-1.5 text-xs font-medium">{{ t('returns.cancellationReason') }}<textarea v-model="cancelForm.reason" required maxlength="500" class="admin-control min-h-24 p-3" /></label><FieldError :message="localizedError(cancelForm.errors.reason ?? serverErrors.return)" /><button :disabled="cancelForm.processing" class="mt-3 w-full rounded-md border border-admin-border-strong bg-white px-4 py-2.5 text-sm font-semibold disabled:opacity-50 sm:w-auto">{{ cancelForm.processing ? t('returns.processing') : t('returns.cancelReturn') }}</button></form></section>
    </div></AdminLayout>
</template>
